export function getSilverExtra(city: string): CitySilverExtra | undefined {
  const base = CITY_SILVER_EXTRA[city.toLowerCase()];
  const ext = CITY_SILVER_EXTRA_V2[city.toLowerCase()];
  if (!base) return undefined;
  return { ...base, ...ext };
}
